/* Content: CCEA GCSE subjects → topics → cards. [question, answer] */
const S=[
{id:'eng-lang',n:'English Language',c:'#e0435b',m:'EL',core:true,topics:[
 {id:'persuasive',n:'Persuasive & rhetorical techniques',cards:[
  ["What does AFOREST stand for?","Alliteration, Facts, Opinions, Rhetorical questions, Emotive language, Statistics, Triplets (rule of three)."],
  ["What is the effect of a rhetorical question?","It makes the reader feel directly addressed and pushes them towards the writer's answer without stating it outright."],
  ["Why do writers use the rule of three?","Three items create rhythm and a sense of completeness, making a point sound memorable and convincing."],
  ["What is emotive language?","Word choice deliberately chosen to provoke an emotional reaction — e.g. \"abandoned\" rather than \"left\"."],
  ["What is direct address and why use it?","Using \"you\" to speak to the reader, making the argument feel personal and harder to ignore."],
  ["How should you use statistics persuasively?","Use a small number of precise figures and explain what they mean — unexplained numbers carry no weight."],
  ["What is a counter-argument and why include one?","Acknowledging the opposing view, then dismantling it. It makes you look reasonable and well informed."],
  ["What is anaphora?","Repeating the same word or phrase at the start of successive clauses, for rhythm and emphasis."]]},
 {id:'reading-nonfic',n:'Reading non-fiction & media',cards:[
  ["What is PEEL / PETAL?","Point, Evidence (short quote), Explain the effect, Link back to the question. Always say what the technique makes the reader think or feel."],
  ["What does a question asking you to 'analyse language' want?","Zoom in on individual word choices and techniques, and explain their effect on the reader — not a summary of content."],
  ["How do you compare two texts effectively?","Use comparative connectives (whereas, similarly, in contrast) and compare the same aspect of both texts in one paragraph."],
  ["What is bias in a text?","Presenting one side favourably, through selective facts, loaded language or omission of counter-evidence."],
  ["What is the difference between fact and opinion?","A fact can be verified; an opinion is a belief or judgement, often signalled by modal verbs or evaluative adjectives."],
  ["How do headlines and subheadings affect a reader?","They frame the story before it is read, set expectations and steer interpretation."],
  ["What should you comment on when analysing an image in a media text?","Composition, facial expression, colour, camera angle, and how it supports or undercuts the written text."],
  ["What is 'tone' in a non-fiction text?","The writer's attitude to the subject — e.g. outraged, nostalgic, sardonic — conveyed through word choice and sentence form."]]},
 {id:'creative',n:'Creative & personal writing',cards:[
  ["What makes a strong creative-writing opening?","Start in the action or on a striking detail, use the senses, and withhold information to create intrigue."],
  ["Name four ways to vary sentences.","Short punchy sentences, complex sentences with subordinate clauses, questions, and fronted adverbials or one-word sentences."],
  ["What is 'show, don't tell'?","Convey emotion through action, detail and dialogue rather than naming it: \"her hands shook\" not \"she was scared\"."],
  ["What is pathetic fallacy?","Giving human emotions to weather or nature to reflect mood — a storm during a conflict."],
  ["How should you end a piece of creative writing?","Circular structure, a shift in perspective, or a resonant final image. Avoid \"it was all a dream\"."],
  ["What is a semantic field?","A group of words in a text linked by meaning — e.g. decay, rot, rust — which builds a consistent atmosphere."],
  ["Why vary paragraph length?","A one-line paragraph after several long ones lands like a punch, controlling pace and emphasis."],
  ["What is free indirect speech?","Third-person narration that slips into a character's own idiom and thoughts without quotation marks."]]},
 {id:'exam-skills',n:'Exam technique & planning',cards:[
  ["How should you plan in the exam?","Roughly 5 minutes: identify purpose, audience and form (PAF), list 4–5 paragraph points, pick an opening hook and a strong ending."],
  ["What does PAF stand for?","Purpose, Audience, Form — decide all three before you write a word."],
  ["How do you allocate time in a writing task?","About 10% planning, 75% writing, 15% checking. Leave time to fix spelling, punctuation and grammar."],
  ["What is the most common way to lose marks in the reading paper?","Retelling the text instead of analysing it, and quoting at length rather than selecting short, precise quotations."],
  ["How long should a quotation be?","As short as possible — often a single word or phrase. Embed it inside your own sentence."],
  ["What should you check in the last five minutes?","Sentence demarcation, apostrophes, homophones (their/there/they're), paragraph breaks, and spelling of key terms."]]},
 {id:'spoken',n:'Spoken language & speaking/listening',cards:[
  ["What is Standard English?","The dialect used in formal writing and speech, defined by grammar and vocabulary rather than accent."],
  ["What is the difference between accent and dialect?","Accent is pronunciation only; dialect includes vocabulary and grammar."],
  ["Name three features of spontaneous speech.","Fillers (erm), false starts, repetition, non-fluency features, interruption and overlap."],
  ["What is idiolect?","An individual's distinctive personal way of speaking."],
  ["What is code-switching?","Changing your language or register to suit the audience or situation."],
  ["What makes an effective individual presentation?","Clear structure, varied tone and pace, eye contact, signposting, and handling questions confidently."]]},
 {id:'grammar',n:'Grammar, punctuation & spelling',cards:[
  ["When do you use a semicolon?","To join two closely related independent clauses, or to separate items in a complex list."],
  ["When do you use a colon?","To introduce a list, an explanation or a quotation — the clause before it must be complete."],
  ["What is a subordinate clause?","A clause that cannot stand alone and depends on a main clause: \"Although it was late, she kept working.\""],
  ["Its or it's?","\"It's\" = it is / it has. \"Its\" = belonging to it. No apostrophe for the possessive."],
  ["What is a fronted adverbial?","An adverbial phrase placed at the start of a sentence, followed by a comma: \"Without warning, the lights died.\""],
  ["What is the difference between affect and effect?","\"Affect\" is usually the verb (to influence); \"effect\" is usually the noun (the result)."],
  ["What is a comma splice and how do you fix it?","Joining two independent clauses with only a comma. Fix with a full stop, a semicolon, or a conjunction."]]}]},

{id:'eng-lit',n:'English Literature',c:'#b8326e',m:'LT',core:true,topics:[
 {id:'inspector',n:'An Inspector Calls',cards:[
  ["When is the play set and when was it written?","Set in 1912, before WWI and the sinking of the Titanic; written by J.B. Priestley in 1945. The gap creates dramatic irony."],
  ["What is Priestley's main message?","Social responsibility: \"We are members of one body.\" He attacks capitalist selfishness and class prejudice."],
  ["What is dramatic irony and where does Priestley use it?","When the audience knows something a character doesn't — Birling calls the Titanic \"unsinkable\" and dismisses the chance of war."],
  ["How does Sheila change across the play?","She moves from a sheltered, materialistic girl to the character most willing to accept responsibility and challenge her parents."],
  ["What does the Inspector represent?","A moral force or collective conscience — possibly supernatural. His name, Goole, suggests 'ghoul'."],
  ["How does Priestley use the lighting?","\"Pink and intimate\" before the Inspector arrives, then \"brighter and harder\" — the comfortable illusion is stripped away."],
  ["What is the significance of the final phone call?","A real inspector is on the way: the cycle begins again, and those who learned nothing will face it properly."],
  ["How does Priestley present Mr Birling?","As a self-made capitalist whose confident predictions are all wrong, discrediting his politics before he states them."]]},
 {id:'mice-men',n:'Of Mice and Men',cards:[
  ["Author, date and setting?","John Steinbeck, 1937; set near Soledad, California, during the Great Depression."],
  ["What does the American Dream mean in the novel?","The hope of owning land and being independent — George and Lennie's farm — shown to be unreachable for most."],
  ["Why is the setting called Soledad significant?","Soledad means 'solitude' in Spanish, reinforcing the novel's theme of loneliness."],
  ["How is Curley's wife presented?","Never named, defined by her husband — both a victim of isolation and sexism, and a threat to the men's dream."],
  ["What is the significance of Candy's dog?","Its shooting foreshadows Lennie's death and raises the question of mercy killing."],
  ["How does Crooks reveal the novel's attitude to race?","Segregated in the harness room, he is educated and proud but crushed by the reminder of his powerlessness."],
  ["What is the structure of the novel?","Circular: it opens and closes by the pool on the Salinas River, suggesting an inescapable cycle."]]},
 {id:'blood-brothers',n:'Blood Brothers',cards:[
  ["Who wrote Blood Brothers and when?","Willy Russell, 1983; set in Liverpool from the 1960s to the 1980s."],
  ["What is the central theme?","Class: twins separated at birth live opposite lives, showing that opportunity, not nature, determines fate."],
  ["What is the role of the Narrator?","He acts as a conscience and a figure of fate, repeating the superstition motif and preventing escape from the ending."],
  ["How does Russell use the superstition motif?","Mrs Lyons invents a curse about twins learning the truth — it becomes self-fulfilling and drives the tragedy."],
  ["How does the play open?","With the ending — the deaths of Mickey and Edward — so the audience watches the causes, not the outcome."]]},
 {id:'poetry',n:'Poetry & unseen poetry',cards:[
  ["What is enjambment and what is its effect?","A sentence running over the end of a line without punctuation, creating pace, flow or a sense of overflow."],
  ["What is a caesura?","A pause in the middle of a line, often from punctuation, which breaks rhythm and creates emphasis."],
  ["What is a volta?","A turn in a poem's argument or mood, often at line 9 of a sonnet or before the final couplet."],
  ["What is iambic pentameter?","Five pairs of unstressed-stressed syllables per line — the rhythm closest to natural English speech."],
  ["How should you approach an unseen poem?","Read twice, identify speaker, subject and shift in mood, then analyse form, imagery and sound in relation to meaning."],
  ["What is sibilance and what effects can it have?","Repeated s/sh sounds — can be soothing, whispering, or menacing depending on context."],
  ["What is the difference between a stanza and a verse?","Stanza is the correct term for a grouped set of lines in a poem; 'verse' loosely refers to poetry generally."],
  ["Why does form matter in poetry analysis?","The shape carries meaning — a rigid sonnet can suggest control, fragmented free verse can suggest disorder."]]},
 {id:'shakespeare',n:'Shakespeare',cards:[
  ["What is a soliloquy?","A speech delivered alone on stage revealing a character's private thoughts directly to the audience."],
  ["What is the difference between a soliloquy and an aside?","A soliloquy is a full speech when alone; an aside is a brief remark to the audience unheard by other characters."],
  ["What is a tragic hero?","A noble character whose fatal flaw (hamartia) causes their downfall, often with a moment of recognition."],
  ["Why does Shakespeare switch between verse and prose?","Verse usually marks high status or heightened emotion; prose often marks lower status, comedy or madness."],
  ["What is a motif?","A recurring image or idea — blood, darkness, disease — that builds a play's central concerns."]]},
 {id:'context-method',n:'Context & writer’s methods',cards:[
  ["How do you write about context without bolting it on?","Tie it to a specific quotation and explain how the period shapes the writer's message or the audience's reaction."],
  ["What does AO2 reward?","Analysis of the writer's methods — language, form and structure — and their effects."],
  ["Why should you call them 'the writer' or name them?","It reminds you that choices are deliberate and constructed, which is what the analysis marks reward."],
  ["What is a good essay structure for literature?","Thesis-led introduction, 3–4 paragraphs each developing one argument with embedded quotations, conclusion that answers the question."],
  ["What does 'methods' mean in the question?","Everything the writer chooses to do: imagery, structure, stagecraft, narrative voice, form, symbolism."]]}]},

{id:'maths',n:'Mathematics',c:'#2b43ff',m:'MA',core:true,topics:[
 {id:'number',n:'Number',cards:[
  ["How do you find a percentage increase multiplier?","1 + (percentage ÷ 100). A 15% increase is × 1.15; a 15% decrease is × 0.85."],
  ["Upper and lower bounds of 6.4 to 1 d.p.?","Lower 6.35, upper 6.45."],
  ["What is a reverse percentage?","Finding the original amount: divide by the multiplier. £60 after a 20% rise → 60 ÷ 1.2 = £50."],
  ["How do you write a number in standard form?","a × 10ⁿ where 1 ≤ a < 10. 0.0043 = 4.3 × 10⁻³."],
  ["How do you find the HCF and LCM using prime factors?","HCF: multiply the common prime factors. LCM: multiply the highest power of every prime appearing."],
  ["What is compound interest and its formula?","Interest on interest: final = P × (1 + r/100)ⁿ for n years."],
  ["How do you convert a recurring decimal to a fraction?","Let x be the decimal, multiply by a power of 10 so the recurring parts align, subtract and solve."],
  ["What is a surd and how do you simplify √50?","An irrational root left in exact form. √50 = √25 × √2 = 5√2."]]},
 {id:'algebra',n:'Algebra',cards:[
  ["Quadratic formula?","x = (−b ± √(b² − 4ac)) ÷ 2a"],
  ["What does the discriminant tell you?","b² − 4ac: positive = two real roots, zero = one repeated root, negative = no real roots."],
  ["How do you factorise x² + 7x + 12?","Find two numbers multiplying to 12 and adding to 7 → (x + 3)(x + 4)."],
  ["What is the difference of two squares?","a² − b² = (a + b)(a − b)."],
  ["Gradient of a line through two points?","(y₂ − y₁) ÷ (x₂ − x₁). In y = mx + c, m is the gradient and c the y-intercept."],
  ["How do you solve simultaneous equations by elimination?","Scale one or both equations so one variable has matching coefficients, then add or subtract to eliminate it."],
  ["What does completing the square give you?","(x + p)² + q, where the turning point of the parabola is (−p, q)."],
  ["How do you recognise the graph shapes?","Linear = straight, quadratic = parabola, cubic = S-shape, reciprocal = hyperbola, exponential = rapid growth/decay."],
  ["How do you solve an inequality like 3x − 2 > 7?","Like an equation: 3x > 9, x > 3. Reverse the sign if you multiply or divide by a negative."]]},
 {id:'ratio',n:'Ratio & proportion',cards:[
  ["How do you share £60 in the ratio 2:3?","Total parts 5, so one part is £12 → £24 and £36."],
  ["What is direct proportion?","y = kx: as one doubles, so does the other. The graph is a straight line through the origin."],
  ["What is inverse proportion?","y = k ÷ x: as one doubles, the other halves. The graph is a hyperbola."],
  ["How do you calculate speed, distance and time?","speed = distance ÷ time. Rearrange with the triangle: distance = speed × time."],
  ["What is density and its formula?","Mass per unit volume: ρ = m ÷ V."],
  ["How do you compare two 'best buy' offers?","Find the unit price (cost per gram or per item) for each and compare."]]},
 {id:'geometry',n:'Geometry & measures',cards:[
  ["Area of a trapezium?","½(a + b)h, where a and b are the parallel sides."],
  ["Pythagoras' theorem?","a² + b² = c², where c is the hypotenuse."],
  ["SOH CAH TOA?","sin = opp/hyp, cos = adj/hyp, tan = opp/adj."],
  ["Volume of a cylinder?","πr²h. Curved surface area = 2πrh."],
  ["Interior angles of an n-sided polygon sum to?","(n − 2) × 180°. Exterior angles always sum to 360°."],
  ["Area and circumference of a circle?","Area = πr², circumference = πd = 2πr."],
  ["Name three circle theorems.","Angle in a semicircle is 90°; angles in the same segment are equal; the angle at the centre is twice the angle at the circumference."],
  ["What do congruent and similar mean?","Congruent: identical shape and size. Similar: same shape, different size, with equal angles and a constant scale factor."],
  ["Volume of a sphere and a cone?","Sphere = (4/3)πr³. Cone = (1/3)πr²h."]]},
 {id:'probability',n:'Probability',cards:[
  ["Probability of A and B (independent)?","P(A) × P(B). For 'A or B' (mutually exclusive) add: P(A) + P(B)."],
  ["What does a tree diagram show?","Successive events, with branch probabilities multiplied along a path and added across paths."],
  ["What is conditional probability?","The probability of an event given another has happened — on a tree, the second set of branches changes (without replacement)."],
  ["What is relative frequency?","Experimental probability: number of successes ÷ total trials. It approaches theoretical probability as trials increase."],
  ["What do all probabilities of an event sum to?","1. So P(not A) = 1 − P(A)."]]},
 {id:'statistics',n:'Statistics',cards:[
  ["How do you find the mean from a frequency table?","Σ(fx) ÷ Σf — multiply each value by its frequency, total them, divide by total frequency."],
  ["What does the median tell you that the mean doesn't?","It is unaffected by extreme values, so it better represents skewed data."],
  ["What is the interquartile range and why use it?","Q3 − Q1. It measures the spread of the middle 50%, ignoring outliers."],
  ["What does a scatter graph show?","Correlation between two variables — positive, negative or none. Correlation does not prove causation."],
  ["What is a line of best fit used for?","Estimating values; interpolation (within the data) is reliable, extrapolation (beyond it) is not."],
  ["What is a stratified sample?","A sample with the same proportions of each group as the population, giving a representative result."]]},
 {id:'exam-maths',n:'Exam technique',cards:[
  ["Why must you show your working?","Method marks are awarded even when the final answer is wrong — a bare wrong answer scores zero."],
  ["What does 'give your answer to 3 significant figures' mean?","Count from the first non-zero digit. 0.004987 → 0.00499."],
  ["What should you do with the formula sheet?","Check which formulas are given so you only memorise the ones that aren't — then use it to confirm substitutions."],
  ["How do you check an answer is sensible?","Estimate with rounded numbers first, and check units and magnitude at the end."]]}]},

{id:'fmaths',n:'Further Mathematics',c:'#4b2bd6',m:'FM',topics:[
 {id:'calculus',n:'Differentiation & integration',cards:[
  ["Differentiate axⁿ","anxⁿ⁻¹"],
  ["Integrate xⁿ","xⁿ⁺¹ ÷ (n + 1) + c, for n ≠ −1."],
  ["How do you find a stationary point?","Set dy/dx = 0 and solve; use d²y/dx² to classify (positive = minimum, negative = maximum)."],
  ["What does dy/dx represent?","The gradient of the curve at a point — the instantaneous rate of change."],
  ["How do you find the area under a curve?","Definite integration between the limits: ∫ᵃᵇ f(x) dx."],
  ["What is the equation of a tangent at a point?","Find dy/dx at that x for the gradient m, then use y − y₁ = m(x − x₁)."]]},
 {id:'pure',n:'Algebra & logarithms',cards:[
  ["log a + log b = ?","log(ab). log a − log b = log(a/b), and n log a = log(aⁿ)."],
  ["What is the remainder theorem?","The remainder when f(x) is divided by (x − a) is f(a). If f(a) = 0, (x − a) is a factor."],
  ["Solve 2ˣ = 10","Take logs: x = log10 ÷ log2 ≈ 3.32."],
  ["What is the binomial expansion of (1 + x)ⁿ for small x?","1 + nx + n(n−1)x²/2! + …"]]},
 {id:'matrices',n:'Matrices & vectors',cards:[
  ["Multiply a 2×2 matrix by a column vector (a b; c d)(x; y)?","(ax + by; cx + dy)"],
  ["Determinant of (a b; c d)?","ad − bc. If it is zero the matrix is singular and has no inverse."],
  ["What does a matrix with determinant −1 do geometrically?","It represents a reflection — area is preserved but orientation is reversed."],
  ["How do you find the magnitude of vector (3, 4)?","√(3² + 4²) = 5."]]},
 {id:'mechanics',n:'Mechanics',cards:[
  ["Newton's second law?","F = ma (resultant force = mass × acceleration)."],
  ["SUVAT: v² = ?","v² = u² + 2as. Also v = u + at and s = ut + ½at²."],
  ["What is the difference between mass and weight?","Mass is the quantity of matter (kg); weight is the force of gravity on it, W = mg (N)."],
  ["What is momentum and when is it conserved?","p = mv. Total momentum is conserved in a collision when no external force acts."],
  ["How do you resolve a force on an inclined plane?","Component down the slope = mg sinθ; component perpendicular = mg cosθ."]]},
 {id:'stats-fm',n:'Statistics',cards:[
  ["What is the binomial distribution used for?","A fixed number of independent trials with two outcomes and constant probability: X ~ B(n, p)."],
  ["What is the normal distribution's key property?","Symmetrical about the mean; ~68% within 1 standard deviation, ~95% within 2."],
  ["What does standard deviation measure?","The average distance of values from the mean — the spread of the data."]]}]},
{id:'bio',n:'Biology',c:'#1a9e5f',m:'BI',core:true,topics:[
 {id:'cells',n:'Cells & microscopy',cards:[
  ["Function of the mitochondria?","Site of aerobic respiration, releasing energy for the cell."],
  ["Name three parts of a plant cell not found in animal cells.","Cell wall (cellulose), chloroplasts and a large permanent vacuole."],
  ["What is the function of the nucleus?","Contains DNA and controls the activities of the cell."],
  ["What is the role of the cell membrane?","Controls what enters and leaves the cell — it is selectively permeable."],
  ["What is diffusion?","The net movement of particles from high to low concentration, down a concentration gradient. It is passive."],
  ["What is osmosis?","The diffusion of water from a dilute solution to a more concentrated one through a selectively permeable membrane."],
  ["What is active transport?","Movement of substances against the concentration gradient using energy from respiration."],
  ["How do you calculate magnification?","Magnification = image size ÷ actual size."],
  ["Name three adaptations of a root hair cell.","Long extension for surface area, thin wall for short diffusion distance, many mitochondria for active transport."]]},
 {id:'photosynthesis',n:'Photosynthesis & plants',cards:[
  ["Word equation for photosynthesis?","Carbon dioxide + water → glucose + oxygen (light energy, absorbed by chlorophyll)."],
  ["Name three limiting factors of photosynthesis.","Light intensity, carbon dioxide concentration and temperature."],
  ["What is the function of the stomata?","Pores, mainly on the lower leaf surface, that allow gas exchange and control water loss. Guard cells open and close them."],
  ["What is transpiration?","The loss of water vapour from the leaves, which pulls water up the xylem in the transpiration stream."],
  ["Name four factors that increase the rate of transpiration.","High temperature, low humidity, air movement (wind) and high light intensity."],
  ["Difference between xylem and phloem?","Xylem carries water and minerals up, in dead hollow vessels. Phloem carries dissolved sugars both ways, in living cells (translocation)."],
  ["How is a leaf adapted for photosynthesis?","Large surface area, thin for short diffusion, palisade cells packed with chloroplasts near the top, air spaces in the spongy layer."],
  ["Test for starch in a leaf, and why it shows photosynthesis.","Boil in water, then ethanol to remove chlorophyll, rinse, add iodine — blue-black shows starch, the stored product of photosynthesis."]]},
 {id:'enzymes',n:'Enzymes & digestion',cards:[
  ["What happens to an enzyme above its optimum temperature?","The active site changes shape (denatures), so the substrate no longer fits and the reaction slows or stops."],
  ["What is the lock and key model?","Each enzyme has a specific active site shape that fits only its complementary substrate."],
  ["Which enzyme digests starch, and into what?","Amylase, into maltose and then glucose."],
  ["Which enzyme digests protein and where?","Protease (pepsin in the stomach), into amino acids."],
  ["What does lipase do and what are the products?","Digests lipids into fatty acids and glycerol."],
  ["What is the role of bile?","Made in the liver, stored in the gall bladder; it emulsifies fats into droplets to increase surface area, and neutralises stomach acid."],
  ["Why does pH affect enzymes?","Extremes of pH denature the enzyme by altering the active site. Pepsin works best at pH 2, amylase near pH 7."],
  ["How is the small intestine adapted for absorption?","Very long, folded, covered in villi and microvilli for surface area, with a thin wall and a rich blood supply."]]},
 {id:'genetics',n:'DNA, genetics & variation',cards:[
  ["What is a gene?","A section of DNA that codes for a particular protein, and so for a characteristic."],
  ["What is the structure of DNA?","A double helix of two strands held by complementary base pairs: A–T and C–G."],
  ["What is the difference between a genotype and a phenotype?","Genotype is the alleles present; phenotype is the physical characteristic expressed."],
  ["What are homozygous and heterozygous?","Homozygous: two identical alleles (BB or bb). Heterozygous: two different alleles (Bb)."],
  ["How do you interpret a Punnett square for Bb × Bb?","3:1 ratio — 3 showing the dominant characteristic to 1 recessive."],
  ["How is sex determined in humans?","XX female, XY male. The father's gamete determines the sex."],
  ["What is a mutation?","A random change in the DNA base sequence, which may alter the protein produced. Most are neutral or harmful."],
  ["Difference between continuous and discontinuous variation?","Continuous: a range of values, e.g. height. Discontinuous: distinct categories, e.g. blood group."],
  ["What is mitosis used for and what does it produce?","Growth, repair and asexual reproduction — two genetically identical diploid cells."],
  ["How does meiosis differ from mitosis?","It produces four genetically different haploid gametes, halving the chromosome number."]]},
 {id:'homeostasis',n:'Homeostasis & nervous system',cards:[
  ["Role of insulin?","Released by the pancreas when blood glucose is high; causes the liver to convert glucose to glycogen, lowering blood glucose."],
  ["What is the role of glucagon?","Released when blood glucose is low; converts glycogen back to glucose in the liver."],
  ["What is Type 1 diabetes and how is it treated?","The pancreas produces little or no insulin; treated with insulin injections, diet and exercise."],
  ["What is a reflex arc?","Receptor → sensory neurone → relay neurone (spinal cord) → motor neurone → effector. Fast and automatic, protecting the body."],
  ["What is a synapse and how is a signal passed across it?","The gap between neurones; a neurotransmitter diffuses across and triggers an impulse in the next neurone."],
  ["How does the body respond to being too hot?","Vasodilation, sweating and hairs lying flat increase heat loss."],
  ["How does the body respond to being too cold?","Vasoconstriction, shivering, hairs standing up and less sweating conserve heat."],
  ["What is negative feedback?","A change triggers a response that reverses it, returning conditions to the set point."],
  ["What is the function of the kidneys?","Filter the blood, removing urea and excess water and salts, and regulate water balance (osmoregulation)."]]},
 {id:'respiration',n:'Respiration & exercise',cards:[
  ["Aerobic vs anaerobic respiration in muscles?","Aerobic: glucose + oxygen → CO₂ + water (lots of energy). Anaerobic: glucose → lactic acid (less energy, oxygen debt)."],
  ["What is the equation for aerobic respiration?","Glucose + oxygen → carbon dioxide + water (+ energy released)."],
  ["What is oxygen debt?","The extra oxygen needed after exercise to break down the lactic acid that built up."],
  ["What happens to heart rate and breathing during exercise, and why?","Both increase to deliver more oxygen and glucose to muscles and remove CO₂ faster."],
  ["Anaerobic respiration in yeast?","Glucose → ethanol + carbon dioxide — fermentation, used in brewing and baking."]]},
 {id:'defence',n:'Body defence & health',cards:[
  ["What do antibiotics treat?","Bacterial infections only, not viruses. Overuse leads to resistant bacteria such as MRSA."],
  ["How does the body defend itself against pathogens?","Skin barrier, mucus and cilia, stomach acid, then white blood cells — phagocytes engulf, lymphocytes make antibodies."],
  ["How does a vaccine work?","A dead or weakened pathogen triggers antibody production and memory cells, so a real infection is destroyed quickly."],
  ["What is herd immunity?","When enough of a population is immune that the pathogen cannot spread easily, protecting those who are not."],
  ["How do bacteria become antibiotic resistant?","Random mutation gives resistance; antibiotics kill the non-resistant, so the resistant survive and reproduce — natural selection."]]},
 {id:'ecology',n:'Ecological relationships',cards:[
  ["What is a food chain and what do the arrows mean?","A sequence showing feeding relationships; arrows show the direction of energy transfer."],
  ["Why are food chains rarely longer than five links?","Only about 10% of energy passes to the next level — the rest is lost in respiration, movement and waste."],
  ["What is the carbon cycle in outline?","Photosynthesis removes CO₂; respiration, decomposition and combustion return it."],
  ["What is eutrophication?","Fertiliser runoff causes algal bloom, blocking light; plants die, bacteria decompose them and use up oxygen, killing fish."],
  ["What is a quadrat used for?","Estimating the abundance or distribution of a species in a sample area, scaled up to the whole habitat."],
  ["What is meant by biodiversity and why does it matter?","The variety of species in an ecosystem; high biodiversity makes an ecosystem more stable and resilient."]]}]},

{id:'chem',n:'Chemistry',c:'#e07b12',m:'CH',core:true,topics:[
 {id:'atomic',n:'Atomic structure',cards:[
  ["Relative charges of proton, neutron and electron?","+1, 0, −1. Relative masses: 1, 1, ~1/1840."],
  ["What is the atomic number and the mass number?","Atomic number = number of protons. Mass number = protons + neutrons."],
  ["What is an isotope?","Atoms of the same element with the same number of protons but a different number of neutrons."],
  ["How are electrons arranged in shells?","2, 8, 8 for the first three shells. The outer shell electrons determine chemical behaviour."],
  ["What is relative atomic mass?","The weighted average mass of an element's isotopes, compared with 1/12 of a carbon-12 atom."]]},
 {id:'bonding',n:'Bonding & structures',cards:[
  ["What is an ionic bond?","Electrostatic attraction between oppositely charged ions, formed by transferring electrons from a metal to a non-metal."],
  ["Why do ionic compounds conduct only when molten or dissolved?","The ions must be free to move to carry charge; in a solid lattice they are fixed."],
  ["What is a covalent bond?","A shared pair of electrons between two non-metal atoms."],
  ["Why do simple molecular substances have low melting points?","The weak intermolecular forces between molecules need little energy to overcome — the covalent bonds themselves are strong."],
  ["Why can graphite conduct electricity but diamond cannot?","Graphite has one delocalised electron per carbon free to move; in diamond all four outer electrons are bonded."],
  ["Describe metallic bonding.","A lattice of positive ions in a sea of delocalised electrons — strong attraction, so metals conduct and are malleable."],
  ["Why are giant covalent structures very hard?","Many strong covalent bonds must be broken throughout the structure."]]},
 {id:'periodic',n:'Periodic table',cards:[
  ["Why are Group 1 metals more reactive down the group?","The outer electron is further from the nucleus with more shielding, so it is lost more easily."],
  ["Why are Group 7 elements less reactive down the group?","The outer shell is further from the nucleus, so an electron is gained less easily."],
  ["What is a displacement reaction in Group 7?","A more reactive halogen displaces a less reactive one from its compound — chlorine displaces bromine."],
  ["Why are Group 0 elements unreactive?","They have a full outer shell, so they do not need to gain, lose or share electrons."],
  ["Name three properties of transition metals.","High melting points, coloured compounds, often act as catalysts, variable oxidation states."],
  ["How is the modern periodic table arranged?","By increasing atomic number, in groups (same outer electrons, similar properties) and periods (same number of shells)."]]},
 {id:'moles',n:'Quantitative chemistry',cards:[
  ["Moles formula?","moles = mass ÷ Mr"],
  ["How do you calculate percentage yield?","(actual yield ÷ theoretical yield) × 100."],
  ["Why is yield never 100%?","Reaction may be incomplete or reversible, product is lost in transfer or purification, and side reactions occur."],
  ["What is Avogadro's number?","6.02 × 10²³ — the number of particles in one mole."],
  ["How do you work out concentration in g/dm³?","mass of solute (g) ÷ volume (dm³). Remember 1000 cm³ = 1 dm³."],
  ["What is the empirical formula and how do you find it?","The simplest whole-number ratio of atoms: divide each mass by Ar, then divide all by the smallest result."]]},
 {id:'acids',n:'Acids, bases & salts',cards:[
  ["Acid + metal carbonate → ?","Salt + water + carbon dioxide"],
  ["Acid + metal → ?","Salt + hydrogen"],
  ["Acid + base (metal oxide or hydroxide) → ?","Salt + water — neutralisation."],
  ["What ion makes a solution acidic, and alkaline?","H⁺ makes it acidic; OH⁻ makes it alkaline."],
  ["What does the pH scale show?","0–14 measure of acidity. 7 is neutral; each step is a tenfold change in H⁺ concentration."],
  ["How do you make a soluble salt from an insoluble base?","Add excess base to warm acid, filter off the excess, then crystallise the filtrate."],
  ["Test for hydrogen gas?","A lit splint gives a squeaky pop."],
  ["Test for carbon dioxide?","Bubble through limewater: it turns milky/cloudy."],
  ["Test for oxygen?","A glowing splint relights."]]},
 {id:'rates',n:'Rates & energy changes',cards:[
  ["Four ways to increase the rate of reaction?","Raise temperature, increase concentration (or pressure for gases), increase surface area, add a catalyst."],
  ["Explain rate using collision theory.","Reactions happen when particles collide with enough energy (activation energy). More frequent or more energetic collisions = faster rate."],
  ["What does a catalyst do?","Speeds up a reaction by lowering the activation energy, without being used up."],
  ["Exothermic vs endothermic?","Exothermic releases heat (temperature rises) — combustion, neutralisation. Endothermic takes heat in — thermal decomposition."],
  ["What is dynamic equilibrium?","In a closed system, forward and reverse reactions occur at the same rate, so concentrations stay constant."],
  ["How do you measure rate experimentally?","Measure gas volume or mass loss over time, or time a colour change/precipitate forming."]]},
 {id:'organic',n:'Organic chemistry',cards:[
  ["General formula of alkanes?","CₙH₂ₙ₊₂ — saturated, single C–C bonds."],
  ["How do you test for an alkene?","It decolourises bromine water from orange to colourless (alkanes do not)."],
  ["What is fractional distillation?","Separating crude oil into fractions by boiling point — shorter chains rise higher and condense at lower temperatures."],
  ["What is cracking and why is it done?","Breaking long-chain hydrocarbons into shorter, more useful ones and alkenes, using heat and a catalyst."],
  ["What is a polymer?","A long molecule made by joining many small monomers — e.g. ethene → poly(ethene)."],
  ["Why are many polymers an environmental problem?","They are unreactive and non-biodegradable, so they persist in landfill and the ocean."],
  ["What is produced by complete and incomplete combustion?","Complete: CO₂ + water. Incomplete: carbon monoxide (toxic) and soot."]]},
 {id:'electro',n:'Electrochemistry & practicals',cards:[
  ["In electrolysis, what forms at the cathode?","The metal (or hydrogen if the metal is more reactive than hydrogen). Positive ions gain electrons: reduction."],
  ["What forms at the anode?","Non-metals — oxygen, or a halogen if a halide is present. Negative ions lose electrons: oxidation."],
  ["What does OILRIG stand for?","Oxidation Is Loss, Reduction Is Gain (of electrons)."],
  ["Why is cryolite used in aluminium extraction?","It lowers the melting point of aluminium oxide, saving energy."],
  ["How do you test for a chloride ion?","Add dilute nitric acid, then silver nitrate: a white precipitate forms."],
  ["Flame test colours for lithium, sodium, potassium, calcium and copper?","Crimson, yellow, lilac, orange-red and blue-green."]]}]},

{id:'phys',n:'Physics',c:'#0f8fbf',m:'PH',core:true,topics:[
 {id:'motion',n:'Motion & forces',cards:[
  ["Speed formula?","speed = distance ÷ time"],
  ["What is the difference between speed and velocity?","Speed is a scalar (size only); velocity is a vector (size and direction)."],
  ["What does the gradient of a distance-time graph show?","Speed. A curved line means changing speed."],
  ["What does the area under a velocity-time graph show?","The distance travelled. The gradient gives acceleration."],
  ["Acceleration formula?","a = (v − u) ÷ t — change in velocity divided by time."],
  ["Newton's three laws in brief?","1: an object stays at rest or constant velocity unless a resultant force acts. 2: F = ma. 3: every action has an equal and opposite reaction."],
  ["What is terminal velocity?","When drag equals weight, the resultant force is zero and the object falls at a constant speed."],
  ["What affects a car's stopping distance?","Thinking distance (speed, reaction time, alcohol, tiredness) plus braking distance (speed, mass, brakes, road and tyre condition)."],
  ["What is the moment of a force?","Moment = force × perpendicular distance from the pivot. For balance, clockwise moments = anticlockwise moments."]]},
 {id:'energy',n:'Energy & work',cards:[
  ["Kinetic energy?","KE = ½mv²"],
  ["Gravitational potential energy?","GPE = mgh"],
  ["What is work done and its formula?","Energy transferred when a force moves an object: W = F × d."],
  ["Efficiency?","useful energy output ÷ total energy input (× 100 for %)."],
  ["What is the principle of conservation of energy?","Energy cannot be created or destroyed, only transferred from one store to another."],
  ["Power formula?","P = energy transferred ÷ time (watts)."],
  ["Name three renewable energy resources and one drawback each.","Wind (intermittent), solar (weather-dependent), hydroelectric (habitat damage), tidal (limited sites)."],
  ["Name three ways to reduce heat loss from a house.","Loft insulation, cavity wall insulation, double glazing, draught excluders."]]},
 {id:'electricity',n:'Electricity',cards:[
  ["Ohm's law?","V = IR (voltage = current × resistance)"],
  ["Electrical power?","P = IV (also P = I²R)"],
  ["What is current and what is potential difference?","Current is the rate of flow of charge (A); potential difference is the energy transferred per coulomb (V)."],
  ["Charge formula?","Q = It (charge = current × time)."],
  ["Compare series and parallel circuits.","Series: same current everywhere, voltage shared, resistances add. Parallel: voltage the same across branches, current splits, total resistance falls."],
  ["Why is the earth wire needed?","It provides a low-resistance path to earth so a fault causes a large current that blows the fuse, preventing electrocution."],
  ["How do you choose a fuse rating?","Slightly above the normal operating current, calculated with I = P ÷ V."],
  ["How does a filament lamp's resistance change?","It increases as the lamp heats up, so its I-V graph is an S-shaped curve, not a straight line."]]},
 {id:'waves',n:'Waves & light',cards:[
  ["Wave speed equation?","v = fλ (speed = frequency × wavelength)"],
  ["Difference between transverse and longitudinal waves?","Transverse: vibrations perpendicular to travel (light, water). Longitudinal: parallel, with compressions and rarefactions (sound)."],
  ["Order of the electromagnetic spectrum (long to short wavelength)?","Radio, microwave, infrared, visible, ultraviolet, X-ray, gamma."],
  ["State the law of reflection.","The angle of incidence equals the angle of reflection, measured from the normal."],
  ["What is refraction and why does it happen?","A change in direction when a wave changes speed entering a new medium. It bends towards the normal when entering a denser medium."],
  ["What is total internal reflection and the critical angle?","Above the critical angle, light is entirely reflected inside a denser medium — used in optical fibres."],
  ["Give one use and one danger of ultraviolet.","Use: sterilising water, security marking. Danger: skin cancer and eye damage."],
  ["What is the audible range of human hearing?","About 20 Hz to 20 000 Hz. Above that is ultrasound, used in medical imaging and cleaning."]]},
 {id:'nuclear',n:'Atomic & nuclear physics',cards:[
  ["What is half-life?","The time for half the radioactive nuclei in a sample to decay, or for the count rate to halve."],
  ["Alpha, beta, gamma — which is most penetrating?","Gamma (stopped by thick lead/concrete). Alpha is stopped by paper, beta by a few mm of aluminium. Alpha is most ionising."],
  ["What happens to the nucleus in alpha decay?","It loses 2 protons and 2 neutrons: mass number −4, atomic number −2."],
  ["What happens in beta decay?","A neutron becomes a proton and emits an electron: mass number unchanged, atomic number +1."],
  ["What is nuclear fission?","A large unstable nucleus splits when it absorbs a neutron, releasing energy and more neutrons — a chain reaction."],
  ["What is nuclear fusion?","Light nuclei join to form a heavier one, releasing huge energy. It needs extreme temperature and pressure — it powers stars."],
  ["Describe the Rutherford scattering experiment and its conclusion.","Alpha particles fired at gold foil: most passed through, a few deflected sharply — so atoms are mostly empty space with a tiny, dense, positive nucleus."],
  ["Name three sources of background radiation.","Radon gas, cosmic rays, rocks and soil, food and drink, medical procedures."]]},
 {id:'magnetism',n:'Magnetism & electromagnetism',cards:[
  ["How do you make an electromagnet stronger?","More turns on the coil, a larger current, and an iron core."],
  ["What is the motor effect?","A current-carrying wire in a magnetic field experiences a force. Use Fleming's left-hand rule for its direction."],
  ["What is electromagnetic induction?","Moving a conductor through a magnetic field (or changing the field) induces a potential difference."],
  ["How does a transformer work and why only with a.c.?","A changing magnetic field in the iron core induces a voltage in the secondary coil; d.c. produces no change, so no induction."],
  ["Transformer equation?","Vp/Vs = Np/Ns — primary and secondary voltages are in the ratio of the turns."],
  ["Why is electricity transmitted at high voltage?","High voltage means low current, so less energy is lost as heat in the cables."]]},
 {id:'space',n:'Space physics',cards:[
  ["What is the life cycle of a star like the Sun?","Nebula → protostar → main sequence → red giant → white dwarf → black dwarf."],
  ["How does a massive star end its life?","Red supergiant → supernova → neutron star or, if massive enough, a black hole."],
  ["What is red shift and what does it show?","Light from distant galaxies is shifted to longer wavelengths, showing they are moving away — evidence for an expanding universe."],
  ["What is the evidence for the Big Bang?","Red shift of distant galaxies and cosmic microwave background radiation."],
  ["What keeps a planet in orbit?","Gravitational attraction acting as a centripetal force, continually changing the direction of its velocity."]]},
 {id:'practical-phys',n:'Practical skills',cards:[
  ["What is the difference between accuracy and precision?","Accurate: close to the true value. Precise: repeat readings close to each other. You can be precise but inaccurate."],
  ["What is an anomalous result and what do you do with it?","A reading that does not fit the pattern — repeat it, and exclude it from the mean if it remains an outlier."],
  ["Independent, dependent and control variables?","Independent: what you change. Dependent: what you measure. Control: what you keep the same for a fair test."],
  ["Density?","ρ = m ÷ V"]]}]},
{id:'geog',n:'Geography',c:'#2f9e8f',m:'GE',topics:[
 {id:'rivers',n:'Rivers',cards:[
  ["Four types of river erosion?","Hydraulic action, abrasion, attrition, solution."],
  ["Four types of transport?","Traction, saltation, suspension, solution."],
  ["How does a waterfall form?","Soft rock under hard rock erodes faster, creating an overhang that collapses; a plunge pool forms and the waterfall retreats upstream, leaving a gorge."],
  ["How does a meander form?","Faster flow on the outer bend erodes a river cliff; slower flow on the inner bend deposits a slip-off slope."],
  ["How does an ox-bow lake form?","The neck of a meander narrows until the river breaks through in a flood; deposition seals off the old loop."],
  ["Why does a river flood?","Heavy or prolonged rain, snowmelt, saturated or impermeable ground, steep slopes, deforestation and urbanisation."],
  ["Name hard and soft river flood management.","Hard: dams, levees, channel straightening. Soft: afforestation, floodplain zoning, wetland restoration."],
  ["What is the drainage basin hydrological cycle?","Inputs (precipitation), flows (infiltration, throughflow, surface runoff), stores (soil, groundwater) and outputs (evaporation, river discharge)."]]},
 {id:'coasts',n:'Coasts',cards:[
  ["What is longshore drift?","Waves approach at an angle set by the prevailing wind (swash), return straight down the beach (backwash), moving sediment along the coast."],
  ["Name a hard and a soft coastal defence.","Hard: sea wall, groynes, rock armour. Soft: beach nourishment, dune regeneration, managed retreat."],
  ["How does a headland and bay form?","Alternating bands of hard and soft rock: soft rock erodes into bays, resistant rock juts out as headlands."],
  ["Sequence of erosion features on a headland?","Crack → cave → arch → stack → stump."],
  ["Difference between constructive and destructive waves?","Constructive: low, long wavelength, strong swash — build beaches. Destructive: tall, frequent, strong backwash — erode."],
  ["What is a spit and how does it form?","A long ridge of deposited sand where the coast changes direction; longshore drift continues depositing, often curving at the end."]]},
 {id:'weather',n:'Weather & climate',cards:[
  ["Define anticyclone.","An area of high pressure with sinking air, bringing settled dry weather — hot in summer, cold and frosty in winter."],
  ["What is a depression?","An area of low pressure with rising air, bringing cloud, rain and changeable windy weather as fronts pass."],
  ["What happens at a warm front and a cold front?","Warm front: gentle slope, prolonged steady rain. Cold front: steeper, short heavy downpours and a temperature drop."],
  ["What is relief rainfall?","Air is forced to rise over high ground, cools, condenses and rains on the windward side, leaving a rain shadow."],
  ["Name three causes of climate change.","Burning fossil fuels, deforestation, agriculture (methane), industry and transport emissions."],
  ["Name three effects of climate change on the UK and Ireland.","Rising sea levels and coastal flooding, more extreme storms, changing growing seasons and species distribution."]]},
 {id:'tectonics',n:'The restless earth',cards:[
  ["What happens at a destructive plate margin?","Oceanic plate subducts under continental plate, causing violent earthquakes and explosive volcanoes."],
  ["What happens at a constructive margin?","Plates move apart, magma rises to form new crust — gentle volcanoes and mild earthquakes, e.g. Mid-Atlantic Ridge."],
  ["What happens at a conservative margin?","Plates slide past each other; no volcanoes, but friction causes powerful earthquakes, e.g. San Andreas Fault."],
  ["What is the focus and the epicentre?","Focus: where the earthquake starts underground. Epicentre: the point on the surface directly above it."],
  ["Why do people live near volcanoes?","Fertile soils, geothermal energy, tourism, mining, and the perception that an eruption is unlikely in their lifetime."],
  ["Why are the effects of earthquakes worse in LICs?","Poor building standards, dense informal housing, limited emergency services and money for preparation and recovery."]]},
 {id:'population',n:'Population',cards:[
  ["What are the stages of the Demographic Transition Model?","1 high birth/death; 2 death rate falls; 3 birth rate falls; 4 both low; 5 birth below death (declining)."],
  ["What does a wide-based population pyramid show?","High birth rate and a youthful population, typical of a less developed country in stage 2."],
  ["Name push and pull factors of migration.","Push: unemployment, conflict, natural disaster. Pull: jobs, safety, better services and family ties."],
  ["What problems does an ageing population create?","Higher pension and healthcare costs, a smaller working population and a rising dependency ratio."],
  ["What is the dependency ratio?","The proportion of people under 15 and over 64 compared with the working-age population."]]},
 {id:'urban',n:'Changing urban areas',cards:[
  ["What is urbanisation?","An increasing proportion of a country's population living in towns and cities."],
  ["Name the zones of a typical city model.","CBD, inner city, suburbs, rural-urban fringe."],
  ["What is a brownfield site and why use it?","Previously built-on land; redeveloping it protects greenfield countryside and reuses existing services."],
  ["What is counter-urbanisation?","People moving out of cities to rural areas, helped by remote working and transport links."],
  ["Name three features of a sustainable city.","Efficient public transport, renewable energy, recycling, green space and affordable energy-efficient housing."]]},
 {id:'development',n:'Development & environment',cards:[
  ["What is the Human Development Index?","A measure combining life expectancy, education (years of schooling) and income (GNI per capita)."],
  ["What is sustainable development?","Meeting the needs of the present without compromising the ability of future generations to meet theirs."],
  ["What is fair trade?","A scheme guaranteeing producers a fair minimum price plus a premium for community projects."],
  ["Name three indicators of development.","GNI per capita, literacy rate, infant mortality, life expectancy, access to clean water."],
  ["What is the development gap?","The widening difference in wealth and quality of life between the richest and poorest countries."]]},
 {id:'fieldwork',n:'Fieldwork skills',cards:[
  ["What is primary and secondary data?","Primary: collected yourself in the field. Secondary: collected by someone else, e.g. census or maps."],
  ["Name three ways to present fieldwork data.","Bar and line graphs, pie charts, located graphs on maps, cross-sections, scattergraphs."],
  ["What makes a sampling method reliable?","A large enough sample, chosen systematically or randomly to avoid bias, with repeats to check consistency."],
  ["How do you measure river velocity in the field?","Time a float over a measured distance, repeated across the channel, or use a flow meter."]]}]},

{id:'hist',n:'History',c:'#a0522d',m:'HI',topics:[
 {id:'germany',n:'Nazi Germany 1933–45',cards:[
  ["When did Hitler become Chancellor?","30 January 1933."],
  ["What was the Reichstag Fire and why did it matter?","February 1933: the parliament burned; Hitler blamed communists and used it to pass emergency decrees suspending civil rights."],
  ["What was the Enabling Act?","March 1933: allowed Hitler to make laws without the Reichstag for four years — the legal basis of the dictatorship."],
  ["What was the Night of the Long Knives?","June 1934: Hitler had Röhm and SA leaders killed to remove rivals and win army support."],
  ["What were the Nuremberg Laws (1935)?","They stripped Jews of German citizenship and banned marriage between Jews and non-Jews."],
  ["What was Kristallnacht?","9–10 November 1938: a state-organised attack on Jewish homes, shops and synagogues across Germany."],
  ["How did the Nazis control young people?","Hitler Youth and the League of German Maidens, plus a rewritten school curriculum stressing race and loyalty."],
  ["How did the Nazis reduce unemployment?","Public works such as autobahns, rearmament, conscription, and removing women and Jews from the official figures."],
  ["Name two groups who resisted the Nazis.","The Edelweiss Pirates, the White Rose group, the Swing Youth, and the July 1944 Bomb Plot officers."]]},
 {id:'ni-troubles',n:'Northern Ireland c.1965–98',cards:[
  ["What was NICRA and when was it founded?","The Northern Ireland Civil Rights Association, 1967: campaigned for one man one vote, an end to gerrymandering and fair housing allocation."],
  ["What was gerrymandering?","Redrawing electoral boundaries to concentrate nationalist voters into few wards, guaranteeing unionist control of councils."],
  ["What happened at Burntollet Bridge?","January 1969: a People's Democracy march from Belfast to Derry was ambushed by loyalists, raising tensions sharply."],
  ["What was the Battle of the Bogside?","August 1969: three days of rioting in Derry after an Apprentice Boys parade, leading to British troops being deployed."],
  ["What was internment and when was it introduced?","August 1971: imprisonment without trial, almost entirely of nationalists. It increased support for the IRA."],
  ["What happened on Bloody Sunday?","30 January 1972, Derry: British paratroopers shot dead 13 civil rights marchers (a 14th died later)."],
  ["What was direct rule?","March 1972: Stormont was suspended and Northern Ireland was governed directly from Westminster."],
  ["What was the Sunningdale Agreement (1973)?","Set up a power-sharing executive and a Council of Ireland; collapsed in May 1974 after the Ulster Workers' Council strike."],
  ["What were the hunger strikes?","1981: republican prisoners led by Bobby Sands died seeking political status; it boosted Sinn Féin's electoral strategy."],
  ["Anglo-Irish Agreement date and key point?","1985: gave the Irish government a consultative role in Northern Ireland affairs; strongly opposed by unionists."],
  ["What was the Downing Street Declaration?","1993: Britain declared no selfish strategic interest in NI and accepted self-determination, opening the way to ceasefires."],
  ["When was the Good Friday (Belfast) Agreement and what did it set up?","10 April 1998: a power-sharing Assembly elected by STV, North–South bodies, prisoner releases and policing reform, approved by referendums north and south."]]},
 {id:'international',n:'International relations 1945–2003',cards:[
  ["What was the Iron Curtain?","Churchill's 1946 term for the division between Soviet-controlled eastern Europe and the democratic west."],
  ["What was the Truman Doctrine and the Marshall Plan?","1947: US policy of containing communism, backed by $13bn of economic aid to rebuild western Europe."],
  ["What was the Berlin Blockade and Airlift?","1948–49: Stalin blocked land routes into West Berlin; the Allies supplied the city by air for 11 months."],
  ["When was the Berlin Wall built and when did it fall?","Built August 1961; opened November 1989."],
  ["Cuban Missile Crisis?","October 1962: the USSR placed nuclear missiles in Cuba; a US naval quarantine led to their removal after 13 days."],
  ["What was détente?","A 1970s easing of Cold War tension, including SALT arms limitation talks and the Helsinki Agreements."],
  ["What ended the Cold War?","Gorbachev's glasnost and perestroika, the 1989 revolutions in eastern Europe, and the collapse of the USSR in 1991."]]},
 {id:'source-skills',n:'Source analysis & essays',cards:[
  ["What does NOP stand for when evaluating a source?","Nature, Origin, Purpose — what kind of source it is, who made it and when, and why it was made."],
  ["How do you judge a source's reliability?","Consider the author's position and motive, the date, the audience, and whether other evidence corroborates it."],
  ["Does bias make a source useless?","No — a biased source is strong evidence for the attitudes and propaganda of the time."],
  ["How should you structure an essay answer?","A clear line of argument, paragraphs each with a point, specific factual detail and explanation, then a judgement that answers the question."],
  ["Why is precise factual detail important?","Dates, names and figures are what distinguish top-band answers from general description."]]}]},

{id:'re',n:'Religious Studies',c:'#7a4bd0',m:'RS',topics:[
 {id:'marks-gospel',n:"Mark's Gospel",cards:[
  ["What is the Messianic Secret in Mark?","Jesus repeatedly tells people not to reveal that he is the Messiah."],
  ["What happened at Caesarea Philippi?","Peter declares \"You are the Messiah\" — a turning point in Mark's Gospel."],
  ["What is the Transfiguration?","Jesus appears in glory with Moses and Elijah before Peter, James and John; a voice declares him God's Son."],
  ["Parable of the Sower: what is it about?","How people respond differently to the word of God: seeds on path, rocky ground, thorns and good soil."],
  ["What is the significance of the Last Supper?","Jesus reinterprets the Passover meal as his body and blood, instituting the Eucharist."],
  ["What is meant by the Kingdom of God in Mark?","God's rule breaking into the world through Jesus — present now and still to come."]]},
 {id:'ethics',n:'Contemporary ethical issues',cards:[
  ["Define the sanctity of life.","The belief that life is sacred and given by God, so only God should take it away."],
  ["Voluntary vs non-voluntary euthanasia?","Voluntary: at the person's request. Non-voluntary: the person cannot give consent, e.g. in a coma."],
  ["What is the quality of life argument?","That the value of life depends on its condition — used to support euthanasia and some abortion cases."],
  ["Give a religious argument for and against capital punishment.","For: \"an eye for an eye\" and protecting society. Against: \"Do not kill\", the possibility of repentance and forgiveness."],
  ["What is situation ethics?","Joseph Fletcher's view that the most loving action (agape) is right in each situation, rather than fixed rules."],
  ["Name two Christian views on abortion.","Many Catholics oppose it absolutely (sanctity of life from conception); some Protestants accept it as the lesser of two evils."]]},
 {id:'relationships',n:'Personal & marital relationships',cards:[
  ["What is agape?","Selfless, unconditional love; central to Christian ethics."],
  ["What are the purposes of Christian marriage?","Lifelong commitment, mutual support and companionship, and in many traditions the procreation and raising of children."],
  ["What do different Christian denominations teach about divorce?","Catholicism does not recognise divorce (marriage is a sacrament), though annulment is possible; most Protestant churches permit it with regret."],
  ["What is a covenant in the context of marriage?","A solemn, binding promise made before God, not simply a legal contract."]]},
 {id:'philosophy',n:'Philosophy of religion',cards:[
  ["What is the design (teleological) argument?","The order and complexity of the universe imply a designer — Paley's watchmaker analogy."],
  ["What is the cosmological argument?","Everything has a cause; tracing causes back requires a First Cause, which is God."],
  ["What is the problem of evil?","If God is all-loving and all-powerful, why does evil and suffering exist?"],
  ["What is the free will defence?","Genuine love requires freedom to choose, and that freedom allows moral evil."],
  ["Difference between moral and natural evil?","Moral evil is caused by human choices; natural evil arises from nature, e.g. earthquakes and disease."]]},
 {id:'exam-re',n:'Exam technique',cards:[
  ["What does an 'evaluate' question want?","Arguments for and against, including religious views, then a justified conclusion."],
  ["How do you strengthen an RE answer?","Use specific scripture, named teachings and denominational differences rather than general statements."],
  ["How should you reference the Bible?","Name the book, and give the teaching accurately — e.g. \"Love your neighbour as yourself\" (Mark 12)."]]}]},

{id:'french',n:'French',c:'#3557d6',m:'FR',topics:[
 {id:'tenses-fr',n:'Tenses & verbs',cards:[
  ["How do you form the passé composé?","avoir or être (present) + past participle: j'ai mangé, je suis allé(e)."],
  ["Which verbs take être? (DR & MRS VANDERTRAMP)","Devenir, revenir, monter, rester, sortir, venir, aller, naître, descendre, entrer, rentrer, tomber, retourner, arriver, mourir, partir (+ reflexives)."],
  ["How do you form the near future?","aller (present) + infinitive: je vais jouer."],
  ["Imperfect stem and endings?","nous form minus -ons + ais, ais, ait, ions, iez, aient (être: ét-)."],
  ["When do you use the imperfect rather than the perfect?","Imperfect for descriptions, repeated or ongoing past actions; perfect for single completed events."],
  ["How do you form the future tense?","Infinitive (drop the final -e of -re verbs) + ai, as, a, ons, ez, ont: je jouerai."],
  ["Conditional: 'I would like'?","Je voudrais / J'aimerais. The conditional uses the future stem with imperfect endings."],
  ["Translate: 'If I had more money, I would travel.'","Si j'avais plus d'argent, je voyagerais."]]},
 {id:'grammar-fr',n:'Grammar essentials',cards:[
  ["Where do adjectives usually go in French?","After the noun, agreeing in gender and number — but BAGS adjectives (Beauty, Age, Goodness, Size) go before."],
  ["How do you make a sentence negative?","ne … pas around the verb: je ne mange pas. Also ne … jamais, ne … rien, ne … plus."],
  ["What is the difference between savoir and connaître?","savoir: to know a fact or how to do something. connaître: to know or be familiar with a person or place."],
  ["How do you say 'there is / there are'?","Il y a. In the past: il y avait."],
  ["What are the direct object pronouns?","me, te, le/la, nous, vous, les — placed before the verb: je le vois."],
  ["How do you form a question in three ways?","Intonation (Tu viens ?), est-ce que (Est-ce que tu viens ?), or inversion (Viens-tu ?)."]]},
 {id:'topics-fr',n:'Topic vocabulary & opinions',cards:[
  ["Useful opinion phrase to boost your grade?","\"À mon avis, … parce que …\" / \"Ce qui me plaît, c'est …\""],
  ["Give three connectives to extend an answer.","parce que, cependant, de plus, par contre, donc."],
  ["How would you describe your school day?","Les cours commencent à neuf heures et finissent à quinze heures trente. Ma matière préférée est…"],
  ["How do you talk about a past holiday?","L'année dernière, je suis allé(e) en Espagne avec ma famille. Nous avons visité… C'était génial."],
  ["Give a phrase for future plans.","Après le collège, j'ai l'intention de… / je voudrais devenir…"]]},
 {id:'exam-fr',n:'Exam skills',cards:[
  ["How do you prepare for the listening exam?","Read the questions first, predict likely vocabulary, listen for negatives and time markers, and answer in the language required."],
  ["What gets you top marks in the writing task?","A range of tenses, opinions with justification, complex structures and connectives, and accurate verb endings."],
  ["How should you handle unknown words in reading?","Use cognates, context and word families; never leave a blank."]]}]},

{id:'spanish',n:'Spanish',c:'#d23c2c',m:'ES',topics:[
 {id:'tenses-es',n:'Tenses & verbs',cards:[
  ["Preterite endings for -ar verbs?","-é, -aste, -ó, -amos, -asteis, -aron (hablé)."],
  ["Imperfect of -ar verbs?","-aba, -abas, -aba, -ábamos, -abais, -aban."],
  ["When do you use preterite versus imperfect?","Preterite for completed single actions; imperfect for descriptions and repeated or ongoing past actions."],
  ["Near future?","ir a + infinitive: voy a estudiar."],
  ["How do you form the future tense?","Infinitive + é, ás, á, emos, éis, án: estudiaré."],
  ["Conditional: 'I would like'?","Me gustaría."],
  ["Translate: 'When I was young, I used to play football.'","Cuando era joven, jugaba al fútbol."],
  ["How do you form the present continuous?","estar + gerund: estoy estudiando."]]},
 {id:'grammar-es',n:'Grammar essentials',cards:[
  ["Ser vs estar?","Ser: permanent traits, origin, time, profession. Estar: location, temporary states, feelings."],
  ["'I like' vs 'I like (plural things)'?","Me gusta + singular / Me gustan + plural."],
  ["What are the personal pronouns?","yo, tú, él/ella/usted, nosotros, vosotros, ellos/ellas/ustedes."],
  ["Where do adjectives go and how do they agree?","After the noun, agreeing in gender and number: una casa blanca, unos libros rojos."],
  ["How do you say 'there is / there are'?","Hay. In the past: había."],
  ["What is the personal 'a'?","Spanish inserts 'a' before a direct object that is a specific person: Veo a mi hermano."]]},
 {id:'topics-es',n:'Topic vocabulary & opinions',cards:[
  ["Give three ways to express an opinion.","Creo que…, En mi opinión…, Lo que más me gusta es…"],
  ["How would you describe your town?","Vivo en una ciudad en el norte de Irlanda. Hay muchas tiendas pero no hay mucho para los jóvenes."],
  ["How do you talk about a past holiday?","El verano pasado fui a España. Me alojé en un hotel y lo pasé genial."],
  ["Give three connectives.","porque, sin embargo, además, por eso."]]},
 {id:'exam-es',n:'Exam skills',cards:[
  ["What boosts marks in the speaking exam?","Extending answers beyond one sentence, giving opinions and reasons, and using more than one tense."],
  ["How do you deal with a word you don't know when speaking?","Paraphrase — describe it with words you do know rather than stopping."]]}]},

{id:'irish',n:'Irish',c:'#0f9b6b',m:'GA',topics:[
 {id:'tenses-ga',n:'Tenses & verbs',cards:[
  ["Past tense (aimsir chaite) of most verbs?","Lenite the first consonant: chuir mé, dhún mé; add d' before vowels: d'ól mé."],
  ["Future tense ending for broad verbs (e.g. dún)?","-faidh: dúnfaidh mé."],
  ["How do you form the present tense of a broad verb?","Add -ann: dúnann sé."],
  ["What is the modh coinníollach used for?","The conditional — what would happen: dhúnfainn (I would close)."],
  ["How do you say 'I am' and 'I am a teacher'?","Tá mé / Táim. Is múinteoir mé."]]},
 {id:'phrases-ga',n:'Key phrases & opinions',cards:[
  ["How do you say 'my name is'?","Is mise … / … is ainm dom."],
  ["How do you say 'I like'?","Is maith liom …"],
  ["How do you give an opinion?","Sílim go … / Is dóigh liom go … / I mo thuairim …"],
  ["'I would like'?","Ba mhaith liom …"],
  ["How do you say you live somewhere?","Tá mé i mo chónaí i mBéal Feirste."],
  ["How do you ask and answer 'how are you'?","Conas atá tú? — Tá mé go maith, go raibh maith agat."]]},
 {id:'grammar-ga',n:'Grammar features',cards:[
  ["What is lenition (séimhiú)?","Adding an h after the first consonant, changing the sound: bean → bhean."],
  ["What is eclipsis (urú)?","Placing a letter before the first consonant: i mBéal Feirste, ar an gcathaoir."],
  ["What is the difference between 'tá' and 'is'?","'Tá' describes a state or action; 'is' is the copula used for identity and classification."],
  ["How are prepositional pronouns formed?","Preposition + pronoun combine: ag + mé = agam, le + mé = liom."]]}]},
{id:'business',n:'Business Studies',c:'#2e7d5b',m:'BS',topics:[
 {id:'starting',n:'Starting a business',cards:[
  ["What is unlimited liability?","The owner is personally responsible for all business debts, so personal possessions can be at risk (sole traders, partnerships)."],
  ["What is limited liability?","Shareholders can only lose what they invested; the company is a separate legal entity."],
  ["Compare a sole trader and a private limited company.","Sole trader: easy to set up, keeps all profit, unlimited liability. Ltd: limited liability, more capital, but more paperwork and shared control."],
  ["What is an entrepreneur?","Someone who sets up a business, organises resources and takes the financial risk in the hope of profit."],
  ["What should a business plan contain?","Business idea, market research, marketing plan, operations, staffing and financial forecasts."],
  ["Name three sources of finance for a new business.","Owner's savings, bank loan, overdraft, grants, crowdfunding, retained profit (later)."],
  ["What is a franchise?","Buying the right to trade under an established brand, using its name, products and systems, in return for fees."]]},
 {id:'marketing',n:'Marketing',cards:[
  ["The 4Ps of the marketing mix?","Product, Price, Place, Promotion."],
  ["What is market segmentation?","Dividing a market into groups (age, gender, income, location, lifestyle) to target customers better."],
  ["Primary vs secondary market research?","Primary: collected first-hand (surveys, interviews). Secondary: already exists (reports, government data)."],
  ["Name four pricing strategies.","Penetration, skimming, competitive, cost-plus, psychological, promotional."],
  ["What is the product life cycle?","Development, introduction, growth, maturity, decline — with extension strategies used to prolong maturity."],
  ["What is a USP?","Unique selling point — what makes a product different from and better than competitors'."],
  ["Why is branding valuable?","It builds recognition and loyalty, allows premium pricing and makes new product launches easier."]]},
 {id:'finance',n:'Finance',cards:[
  ["Break-even point formula?","Fixed costs ÷ (selling price − variable cost per unit)."],
  ["What is contribution?","Selling price − variable cost per unit — what each sale contributes towards fixed costs and profit."],
  ["Cash flow vs profit?","Cash flow is the movement of money in and out over time; profit is revenue minus total costs. A profitable firm can still run out of cash."],
  ["Gross profit formula?","Revenue − cost of sales."],
  ["Net profit formula?","Gross profit − expenses (overheads)."],
  ["Name three ways to improve cash flow.","Chase debtors, negotiate longer credit with suppliers, reduce stock, arrange an overdraft, cut or delay spending."],
  ["What is the margin of safety?","The difference between actual sales and the break-even level — how far sales can fall before a loss."]]},
 {id:'people',n:'Human resources & operations',cards:[
  ["Maslow's hierarchy (bottom to top)?","Physiological, safety, social, esteem, self-actualisation."],
  ["Name four stakeholders.","Owners/shareholders, employees, customers, suppliers (also the local community and government)."],
  ["Financial vs non-financial motivation?","Financial: wages, bonus, commission, profit share. Non-financial: job rotation, enrichment, teamwork, praise, responsibility."],
  ["What is the recruitment process in order?","Job analysis, job description and person specification, advertise, shortlist, interview and select, induct."],
  ["What is quality assurance versus quality control?","Assurance: preventing faults throughout the process, everyone responsible. Control: inspecting the finished product."],
  ["What is just-in-time stock control?","Stock arrives only as needed — lowers storage costs but risks production stopping if deliveries fail."],
  ["What are economies of scale?","Cost advantages from producing in larger volumes, lowering the average cost per unit."]]}]},

{id:'digi',n:'Digital Technology',c:'#0a7ea4',m:'DT',topics:[
 {id:'data',n:'Digital data',cards:[
  ["Convert 13 to binary.","1101 (8 + 4 + 1)."],
  ["Convert 1010 1010 to denary.","170 (128 + 32 + 8 + 2)."],
  ["How many bits in a byte?","8 bits. A nibble is 4 bits; 1024 bytes = 1 kibibyte."],
  ["What is ASCII?","A character set using 7 or 8 bits to represent letters, digits and symbols as binary numbers."],
  ["How is an image stored digitally?","As pixels, each with a binary colour value. Resolution and colour depth determine quality and file size."],
  ["What is the difference between lossy and lossless compression?","Lossy permanently discards data for smaller files (JPEG, MP3); lossless preserves all data (PNG, ZIP)."]]},
 {id:'hardware',n:'Hardware & software',cards:[
  ["RAM vs ROM?","RAM is volatile, read/write, holds running programs and data. ROM is non-volatile, read-only, holds start-up instructions."],
  ["What does the CPU do and what are its main parts?","Executes instructions; contains the control unit, ALU and registers, using the fetch-decode-execute cycle."],
  ["What is cache memory?","Very fast memory close to the CPU holding frequently used instructions and data, reducing wait time."],
  ["Difference between system software and application software?","System software runs the computer (operating system, utilities); application software performs user tasks."],
  ["Name four functions of an operating system.","Memory management, file management, process/CPU scheduling, peripheral management, user interface, security."],
  ["What is an embedded system?","A computer built into a device for a single purpose — washing machine, car engine management, smart meter."]]},
 {id:'databases',n:'Database applications',cards:[
  ["What is a primary key?","A field that uniquely identifies each record in a database table."],
  ["What is a foreign key?","A field in one table that links to the primary key of another, creating a relationship."],
  ["What is a relational database and why use one?","Data split across linked tables — it avoids duplication, keeps data consistent and makes updates easier."],
  ["What is a query?","A request to retrieve or manipulate specific data meeting given criteria."],
  ["What is validation and what are three types?","Checking data is sensible on entry: range check, format check, presence check, length check, type check."],
  ["Validation vs verification?","Validation checks data is reasonable; verification checks it has been entered accurately, e.g. double entry or proofreading."]]},
 {id:'networks',n:'Networks & security',cards:[
  ["Star topology: one advantage, one disadvantage?","Advantage: one cable failing affects only one device. Disadvantage: if the central switch fails, the whole network fails."],
  ["Difference between a LAN and a WAN?","LAN covers a small area on owned infrastructure; WAN covers a wide area using third-party connections."],
  ["What is cloud computing?","Storing data or running software on remote servers accessed over the internet."],
  ["What is phishing?","Fake emails or messages pretending to be from a trusted organisation to trick people into giving personal details."],
  ["What is malware? Name three types.","Software designed to damage or gain access: virus, worm, trojan, ransomware, spyware."],
  ["What is encryption?","Scrambling data with a key so that intercepted data is unreadable without the decryption key."],
  ["Name four ways to secure a network.","Strong passwords, two-factor authentication, firewall, anti-malware, encryption, access levels, regular updates."],
  ["What is the Computer Misuse Act 1990?","Makes unauthorised access to computer material, access with intent to commit further offences, and unauthorised modification illegal."],
  ["What does data protection law require of organisations?","Data must be processed lawfully and fairly, kept accurate, secure, used only for stated purposes and not kept longer than necessary."]]},
 {id:'programming',n:'Programming concepts',cards:[
  ["What are the three basic programming constructs?","Sequence, selection (if/else) and iteration (loops)."],
  ["What is an algorithm?","A step-by-step set of instructions for solving a problem."],
  ["What is a variable versus a constant?","A variable's value can change while the program runs; a constant's cannot."],
  ["What is a syntax error versus a logic error?","Syntax breaks the language rules and won't run; logic runs but gives the wrong result."],
  ["What is a function and why use one?","A named reusable block of code; it reduces duplication and makes programs easier to test and maintain."],
  ["What is pseudocode used for?","Planning an algorithm in structured English before coding it in a specific language."]]}]},

{id:'food',n:'Food & Nutrition',c:'#d1692b',m:'FN',topics:[
 {id:'nutrients',n:'Nutrients & health',cards:[
  ["Functions of protein?","Growth, repair and maintenance of body tissues; a secondary energy source."],
  ["What is the difference between HBV and LBV protein?","High biological value contains all essential amino acids (meat, fish, eggs, soya); low biological value lacks one or more (most plants)."],
  ["Which vitamin helps absorb iron?","Vitamin C. Iron deficiency can cause anaemia."],
  ["What are the functions of calcium and which vitamin aids it?","Strong bones and teeth and blood clotting; vitamin D aids absorption. Deficiency causes rickets or osteoporosis."],
  ["Why is fibre important?","It adds bulk, aids digestion and prevents constipation, bowel disease and helps control appetite."],
  ["What does the Eatwell Guide show?","The proportions of food groups for a healthy balanced diet: fruit & veg, starchy carbohydrates, protein, dairy, small amounts of oils."],
  ["Name three diet-related health conditions.","Obesity, type 2 diabetes, coronary heart disease, tooth decay, anaemia, osteoporosis."],
  ["What are the fat-soluble vitamins?","A, D, E and K — stored in the body, unlike water-soluble B and C."]]},
 {id:'safety',n:'Food safety & hygiene',cards:[
  ["What is the temperature danger zone?","5°C to 63°C: bacteria multiply fastest; keep cold food below 5°C and hot food above 63°C."],
  ["Name four food poisoning bacteria and a source of each.","Salmonella (raw poultry, eggs), E. coli (undercooked beef), Campylobacter (raw chicken), Listeria (soft cheese, pâté)."],
  ["What four conditions do bacteria need to multiply?","Warmth, moisture, food and time (most also need a suitable pH)."],
  ["What is cross-contamination and how do you prevent it?","Transfer of bacteria from raw to ready-to-eat food. Prevent with separate boards, handwashing and correct fridge storage."],
  ["What core temperature should cooked food reach?","75°C for at least two minutes, checked with a temperature probe."],
  ["Difference between use-by and best-before?","Use-by is a safety date for perishable food; best-before relates to quality only."]]},
 {id:'science-food',n:'Food science & preparation',cards:[
  ["What is gelatinisation?","Starch granules absorb liquid when heated, swell and burst, thickening a sauce (around 60–80°C+)."],
  ["What is denaturation?","Heat, acid or agitation unravel protein structure — e.g. an egg setting when cooked."],
  ["What is aeration and give an example?","Trapping air to lighten a mixture — whisking egg whites, creaming butter and sugar."],
  ["What is the function of each ingredient in pastry?","Flour: structure. Fat: shortening and flavour. Water: binds. Salt: flavour and strengthens gluten."],
  ["What is the Maillard reaction?","Browning between proteins and sugars at high temperature, giving flavour and colour to roasted and baked food."],
  ["Name three raising agents.","Baking powder, bicarbonate of soda, yeast, steam, trapped air."]]},
 {id:'provenance',n:'Food provenance & consumer issues',cards:[
  ["What is food provenance?","Where food comes from: how and where it was grown, reared, caught or made."],
  ["What are food miles and why do they matter?","The distance food travels to the consumer; more miles usually means higher carbon emissions."],
  ["What is seasonality and one benefit of eating seasonally?","Eating food when it naturally grows locally — fresher, cheaper, lower environmental impact."],
  ["Name three things that must appear on a food label by law.","Name of food, ingredients list with allergens emphasised, weight, use-by/best-before date, storage and nutrition information."],
  ["What is food security?","Reliable access for all people to sufficient, safe and nutritious food."]]}]},

{id:'llw',n:'Learning for Life & Work',c:'#c2410c',m:'LW',topics:[
 {id:'citizenship',n:'Local & global citizenship',cards:[
  ["What is the UNCRC?","The UN Convention on the Rights of the Child: 54 articles setting out the rights of every child under 18."],
  ["What does the Equality Commission for NI do?","Promotes equality and tackles discrimination in employment and services in Northern Ireland."],
  ["Name three features of a democracy.","Free and fair elections, rule of law, freedom of speech and the press, protection of human rights."],
  ["Name a pressure group method.","Petitions, protests, lobbying politicians, social media campaigns, strikes, publicity stunts."],
  ["What is meant by diversity and inclusion?","Recognising and valuing differences, and ensuring everyone can take part fully regardless of background."],
  ["What is social exclusion?","When individuals or groups are shut out of full participation in society through poverty, discrimination or lack of access."]]},
 {id:'employability',n:'Employability',cards:[
  ["What should a CV include?","Personal details, personal profile, education & qualifications, work experience, skills, interests, referees."],
  ["Name four employability skills.","Communication, teamwork, problem solving, time management, IT skills, reliability, flexibility."],
  ["How should you prepare for an interview?","Research the employer, re-read the job description, prepare examples of your skills, plan questions, dress appropriately and arrive early."],
  ["Name three rights of an employee.","A written contract, the national minimum wage, paid holiday, a safe workplace, protection from discrimination."],
  ["What is self-employment and one advantage and disadvantage?","Working for yourself: freedom and keeping profits, but no sick pay, irregular income and full responsibility."],
  ["What is lifelong learning and why does it matter?","Continuing to learn and retrain throughout a career, needed because technology and job markets change."]]},
 {id:'personal-dev',n:'Personal development',cards:[
  ["Name three influences on self-esteem.","Family, friends, school experience, social media, achievements and failures."],
  ["What makes a healthy relationship?","Mutual respect, trust, honest communication, consent and equality."],
  ["Name three ways to manage stress.","Exercise, sleep, talking to someone, time management, relaxation techniques, limiting screen time."],
  ["What are the risks of substance misuse?","Physical and mental health damage, addiction, legal consequences, strained relationships and money problems."],
  ["How can you manage personal finances well?","Budget income against spending, save regularly, avoid high-interest borrowing, understand APR before taking credit."]]}]},

{id:'art',n:'Art & Design',c:'#c0367f',m:'AD',topics:[
 {id:'elements',n:'Formal elements & techniques',cards:[
  ["What are the formal elements?","Line, tone, colour, shape, form, texture, pattern (and space/composition)."],
  ["Complementary colours?","Opposites on the colour wheel: red–green, blue–orange, yellow–purple."],
  ["What are primary, secondary and tertiary colours?","Primary: red, yellow, blue. Secondary: orange, green, purple. Tertiary: a primary mixed with an adjacent secondary."],
  ["What is tone and why does it matter?","The lightness or darkness of a colour — it creates the illusion of form and depth."],
  ["Name three mark-making techniques.","Hatching, cross-hatching, stippling, scumbling, blending."],
  ["What is composition and name one rule used to plan it?","How elements are arranged in a work; the rule of thirds places focal points on intersecting third-lines."],
  ["What is the difference between form and shape?","Shape is two-dimensional; form is three-dimensional and implies volume."]]},
 {id:'portfolio',n:'Portfolio & annotation',cards:[
  ["How should you annotate your sketchbook?","Explain why you chose techniques, what worked, what didn't, and how an artist influenced your next step."],
  ["How do you analyse an artist's work?","Content (what), form (how it's made), process (techniques), mood (feelings), and how it links to your own ideas."],
  ["What makes development strong?","A clear journey from research to experiments to refined ideas, with each step responding to the last."],
  ["What should your final piece show?","A resolved outcome that clearly connects to your research, experiments and chosen artist influences."],
  ["Why record work in progress?","Evidence of process is assessed — photograph stages, including failed experiments and what you learned."]]},
 {id:'industries',n:'Creative & cultural industries',cards:[
  ["Name four careers in the creative industries.","Graphic designer, illustrator, architect, fashion designer, animator, curator, photographer, product designer."],
  ["What does a curator do?","Selects, arranges and interprets works for an exhibition, and writes the supporting material."],
  ["Why is copyright important for artists?","It protects original work from being copied or used commercially without permission or payment."]]}]},

{id:'music',n:'Music',c:'#8a3ffc',m:'MU',topics:[
 {id:'elements-mu',n:'Musical elements',cards:[
  ["What does DR SMITH stand for?","Dynamics, Rhythm, Structure, Melody, Instrumentation, Texture, Harmony — the elements to comment on."],
  ["What is an ostinato?","A short musical pattern repeated persistently."],
  ["Define syncopation.","Accenting off-beats or weak beats, making the rhythm feel off-balance."],
  ["What does 'pizzicato' mean?","Plucking the strings of a bowed instrument."],
  ["Name four dynamic markings from quiet to loud.","pp (pianissimo), p (piano), mf (mezzo-forte), f (forte), ff (fortissimo)."],
  ["What is texture? Name three types.","How many layers of sound and how they interact: monophonic, homophonic, polyphonic."],
  ["What does tempo marking allegro mean, and andante?","Allegro: fast and lively. Andante: at a walking pace."]]},
 {id:'harmony',n:'Harmony & structure',cards:[
  ["Perfect vs plagal cadence?","Perfect: V–I (sounds finished). Plagal: IV–I (the \"Amen\" cadence)."],
  ["Imperfect and interrupted cadences?","Imperfect ends on V (unfinished). Interrupted: V–VI (surprise)."],
  ["Ternary vs rondo form?","Ternary: ABA. Rondo: ABACA — the main theme returns between contrasting sections."],
  ["What is a modulation?","A change of key within a piece, often to the dominant or relative minor."],
  ["What is the difference between major and minor tonality?","Major usually sounds bright; minor usually sounds darker, with a flattened third."],
  ["What is binary form?","Two contrasting sections, AB, each usually repeated."]]},
 {id:'performing',n:'Performing & composing',cards:[
  ["What is assessed in the performing component?","Accuracy, fluency, technical control, interpretation and communication, at an appropriate level of demand."],
  ["Name three things to plan before composing.","Key and time signature, structure, intended style and instrumentation, and how material will develop."],
  ["What is development in composition?","Taking a motif and varying it — sequence, inversion, augmentation, diminution, changing instrumentation."],
  ["Why is a score or lead sheet useful?","It communicates your intentions precisely and is often required evidence for the composition submission."]]}]},

{id:'pe',n:'Physical Education',c:'#0e9f6e',m:'PE',topics:[
 {id:'fitness',n:'Health, training & fitness',cards:[
  ["What does FITT stand for?","Frequency, Intensity, Time, Type."],
  ["Name the health-related components of fitness.","Cardiovascular endurance, muscular endurance, muscular strength, flexibility, body composition."],
  ["Skill-related components of fitness?","Agility, balance, coordination, power, reaction time, speed."],
  ["What does SMART stand for?","Specific, Measurable, Achievable, Realistic, Time-bound."],
  ["Maximum heart rate estimate and training zones?","220 − age. Aerobic training zone is roughly 60–80% of maximum heart rate."],
  ["Name four training methods.","Continuous, fartlek, interval, circuit, weight, plyometric training."],
  ["What are the principles of training?","Specificity, progressive overload, reversibility, tedium (SPORT), plus individual needs and rest."],
  ["Why are warm-up and cool-down important?","Warm-up raises heart rate and muscle temperature, reducing injury risk; cool-down removes waste products and reduces soreness."]]},
 {id:'physiology',n:'Exercise physiology',cards:[
  ["Aerobic vs anaerobic exercise?","Aerobic uses oxygen for long, steady activity. Anaerobic is without oxygen for short, high-intensity bursts, producing lactic acid."],
  ["Name the short-term effects of exercise.","Increased heart rate, breathing rate and depth, raised body temperature, sweating, muscle fatigue."],
  ["Name four long-term effects of training.","Lower resting heart rate, stronger heart (hypertrophy), increased lung capacity, improved muscle strength, better recovery."],
  ["What is cardiac output?","Stroke volume × heart rate — the volume of blood the heart pumps per minute."],
  ["What are the main functions of the skeleton?","Support, protection, movement, blood cell production and mineral storage."],
  ["Name the main muscle groups used in a sprint.","Quadriceps, hamstrings, gluteals, gastrocnemius, plus core stabilisers."],
  ["What is an antagonistic muscle pair? Give an example.","One muscle contracts while its partner relaxes — biceps and triceps at the elbow."]]},
 {id:'performance',n:'Performance, injury & analysis',cards:[
  ["RICE treatment?","Rest, Ice, Compression, Elevation (for soft-tissue injuries)."],
  ["Name three causes of sports injuries.","Poor technique, inadequate warm-up, overuse, incorrect equipment, foul play, fatigue."],
  ["How do you analyse performance?","Identify strengths and weaknesses against the demands of the activity, then set a SMART action plan to improve."],
  ["What are the benefits of exercise for mental health?","Reduced stress and anxiety, improved mood through endorphins, better sleep and self-esteem."],
  ["Name three factors affecting participation in sport.","Cost, access and facilities, gender stereotypes, disability provision, time, cultural attitudes."]]}]},

{id:'tech',n:'Technology & Design',c:'#4b5563',m:'TD',topics:[
 {id:'materials',n:'Materials & processes',cards:[
  ["Thermoplastic vs thermosetting plastic?","Thermoplastics soften when heated and can be reshaped (acrylic). Thermosets set permanently (epoxy resin, melamine)."],
  ["Ferrous vs non-ferrous metal?","Ferrous contains iron and is usually magnetic (mild steel). Non-ferrous doesn't (aluminium, copper, brass)."],
  ["Hardwood vs softwood?","Hardwood comes from deciduous broad-leaved trees (oak, beech); softwood from coniferous trees (pine, spruce). Not a measure of hardness."],
  ["Name three ways to join wood.","Butt joint, dowel joint, mortise and tenon, dovetail, screws and adhesive."],
  ["What is a jig and why use one?","A device that guides a tool or holds work in position, giving accuracy and repeatability in batch production."],
  ["What is vacuum forming?","Heating a thermoplastic sheet until pliable and sucking it over a mould to take its shape."]]},
 {id:'design',n:'Design principles',cards:[
  ["What is anthropometrics?","The study of human body measurements, used to size products."],
  ["What is ergonomics?","Designing products to be comfortable, safe and efficient for people to use."],
  ["What is CAD/CAM?","Computer-aided design and computer-aided manufacture — e.g. laser cutter, 3D printer, CNC router."],
  ["What should a design specification include?","Function, performance requirements, materials, size, cost, safety, aesthetics, sustainability and target market."],
  ["What are the 6 Rs of sustainable design?","Rethink, Refuse, Reduce, Reuse, Repair, Recycle."],
  ["Why produce prototypes?","To test a design's function, size and appearance and identify improvements before committing to manufacture."]]},
 {id:'systems',n:'Systems & control',cards:[
  ["What is a potential divider used for?","Splitting voltage, e.g. with an LDR or thermistor to make a sensing circuit."],
  ["Gear ratio?","Number of teeth on driven gear ÷ number of teeth on driver gear."],
  ["What does an LDR do and where is it used?","Resistance falls as light increases — used in light-sensing circuits such as automatic lighting."],
  ["What does a transistor do in a circuit?","Acts as an electronic switch or amplifier, turning on an output when the base voltage reaches about 0.7V."],
  ["Name three classes of lever with an example.","Class 1: seesaw. Class 2: wheelbarrow. Class 3: tweezers."],
  ["What is the purpose of a capacitor in a timing circuit?","It charges through a resistor at a known rate, setting the time delay before an output switches."]]}]},

{id:'mia',n:'Moving Image Arts',c:'#111827',m:'MI',topics:[
 {id:'film-language',n:'Film language',cards:[
  ["What is the 180-degree rule?","Keep the camera on one side of an imaginary line between two characters so their screen positions stay consistent."],
  ["Diegetic vs non-diegetic sound?","Diegetic exists in the story world (dialogue, footsteps). Non-diegetic is added for the audience (score, voice-over)."],
  ["What is mise-en-scène?","Everything in the frame: setting, props, costume, make-up, lighting, actors' performance and positioning."],
  ["High-angle vs low-angle shot?","High angle looks down, making a subject seem weak; low angle looks up, making them seem powerful."],
  ["What is a shot-reverse-shot?","Alternating between two characters' viewpoints in a conversation."],
  ["Name four camera shot sizes.","Extreme long shot, long shot, mid shot, close-up, extreme close-up."],
  ["What is a tracking shot versus a pan?","Tracking moves the camera through space; a pan pivots the camera from a fixed position."],
  ["What is three-point lighting?","Key light, fill light and back light — the standard setup for modelling a subject."]]},
 {id:'editing',n:'Editing & structure',cards:[
  ["What is a match on action?","A cut from one shot to another that continues the same movement, making the edit invisible."],
  ["What is continuity editing?","Editing that maintains a consistent, logical flow of time and space so the cuts go unnoticed."],
  ["What is montage?","A sequence of short shots condensing time or building an idea through juxtaposition."],
  ["What is a jump cut and what effect does it create?","A cut between two similar shots that breaks continuity, creating disorientation or urgency."],
  ["What is cross-cutting (parallel editing)?","Cutting between two actions happening simultaneously in different places, building tension."],
  ["What is a cutaway?","A shot of something other than the main action, used to add information or cover an edit."]]},
 {id:'preproduction',n:'Pre-production & genre',cards:[
  ["What should a storyboard show?","Each shot's framing, camera movement, action, dialogue and timing — a visual plan of the edit."],
  ["What is in a shooting script?","Scene headings, action, dialogue and technical directions for each shot, in production order."],
  ["Name three conventions of the horror genre.","Low-key lighting, isolated setting, point-of-view shots, sudden non-diegetic stings, an unseen threat."],
  ["What is German Expressionism known for?","Distorted sets, extreme shadows and stylised performance — a major influence on horror and film noir."],
  ["What is an auteur?","A director whose personal style and recurring themes mark their films as distinctly theirs."]]}]},

{id:'econ',n:'Economics',c:'#155e75',m:'EC',topics:[
 {id:'basics',n:'The economic problem',cards:[
  ["What is opportunity cost?","The value of the next best alternative given up when making a choice."],
  ["What is the basic economic problem?","Scarcity: unlimited wants but limited resources."],
  ["What are the factors of production?","Land, labour, capital and enterprise."],
  ["What is meant by the allocation of resources?","Deciding what to produce, how to produce it and for whom — answered by the market, the state or a mix."],
  ["What is specialisation and one benefit and risk?","Concentrating on what you do best: higher productivity, but dependence on others and vulnerability to disruption."]]},
 {id:'markets',n:'Markets & prices',cards:[
  ["What happens to demand when price rises?","Quantity demanded falls — a movement along the demand curve, all else equal."],
  ["Name three factors that shift the demand curve.","Income, tastes and fashion, price of substitutes or complements, population, advertising."],
  ["Price elastic demand means?","A change in price causes a proportionally larger change in quantity demanded (PED > 1)."],
  ["What is equilibrium price?","The price where quantity demanded equals quantity supplied, clearing the market."],
  ["What causes the supply curve to shift?","Production costs, technology, taxes and subsidies, weather and number of producers."],
  ["What is market failure? Give two examples.","When markets allocate resources inefficiently — pollution (negative externality), under-provision of public goods, monopoly."]]},
 {id:'economy',n:'Government & the economy',cards:[
  ["What is inflation and how is it measured in the UK?","A sustained rise in the general price level; measured using the Consumer Prices Index (CPI)."],
  ["What is GDP?","Gross domestic product: the total value of goods and services produced in a country in a year."],
  ["Name the main government economic objectives.","Low inflation, low unemployment, economic growth, balance of payments stability, fair income distribution."],
  ["What is fiscal policy versus monetary policy?","Fiscal: government taxation and spending. Monetary: interest rates and money supply, set by the Bank of England."],
  ["How do higher interest rates reduce inflation?","Borrowing costs more and saving pays more, so spending and demand fall, easing price rises."],
  ["What are the main types of unemployment?","Frictional, structural, cyclical and seasonal."],
  ["What is the difference between direct and indirect tax?","Direct is paid on income or profit (income tax); indirect is paid on spending (VAT)."]]},
 {id:'trade',n:'International trade & personal finance',cards:[
  ["What are imports and exports?","Imports are goods and services bought from abroad; exports are those sold abroad."],
  ["What are the benefits of international trade?","Wider choice, lower prices through comparative advantage, larger markets and economies of scale."],
  ["What is a tariff and a quota?","A tariff is a tax on imports; a quota is a physical limit on the quantity imported."],
  ["How does a weaker currency affect trade?","Exports become cheaper abroad and imports dearer, which can improve the trade balance but raise inflation."],
  ["What is APR and why does it matter?","Annual Percentage Rate — the true yearly cost of borrowing, allowing fair comparison between credit deals."]]}]},

{id:'cd',n:'Child Development',c:'#db2777',m:'CD',topics:[
 {id:'pregnancy',n:'Pregnancy & birth',cards:[
  ["Why take folic acid before and in early pregnancy?","It reduces the risk of neural tube defects such as spina bifida."],
  ["Name three things to avoid in pregnancy.","Alcohol, smoking, soft unpasteurised cheese, pâté, raw eggs, liver (excess vitamin A), certain medicines."],
  ["What is antenatal care?","Regular checks during pregnancy — scans, blood pressure, urine tests and classes preparing for birth."],
  ["What are the three stages of labour?","Dilation of the cervix, delivery of the baby, delivery of the placenta."],
  ["What is the Apgar score?","A check at 1 and 5 minutes after birth scoring appearance, pulse, grimace, activity and respiration out of 10."],
  ["Name three benefits of breastfeeding.","Provides antibodies, correct nutrient balance, promotes bonding, free and always the right temperature."]]},
 {id:'development',n:'Development & milestones',cards:[
  ["PIES stands for?","Physical, Intellectual, Emotional, Social development."],
  ["What is a milestone?","A skill most children achieve by a certain age, e.g. walking around 12 months."],
  ["Fine vs gross motor skills?","Fine: small movements (pincer grip, drawing). Gross: large movements (crawling, running)."],
  ["Name three milestones in the first year.","Smiling (6 weeks), sitting unsupported (6–8 months), crawling (8–10 months), first words (around 12 months)."],
  ["What is attachment and why does it matter?","The strong emotional bond with a main carer; secure attachment supports confidence and later relationships."],
  ["What is the sequence of language development?","Crying, cooing, babbling, first words (12 months), two-word phrases (2 years), sentences (3 years)."]]},
 {id:'play',n:'Play & childcare',cards:[
  ["Name three types of play.","Solitary, parallel, cooperative (also creative, imaginative, physical, manipulative)."],
  ["Why is play important for development?","It develops all PIES areas — coordination, problem solving, language, confidence and sharing."],
  ["Name three childcare provisions.","Childminder, day nursery, playgroup, nursery school, after-school club, family care."],
  ["How can a carer keep a toddler safe at home?","Stair gates, socket covers, cupboard locks, safe storage of chemicals and medicines, constant supervision near water."],
  ["What are the signs of a healthy, well-cared-for child?","Appropriate growth, alertness, curiosity, good appetite and sleep, confident interaction with carers."]]}]},

{id:'hsc',n:'Health & Social Care',c:'#0d9488',m:'HS',topics:[
 {id:'lifestages',n:'Life stages & development',cards:[
  ["Life stages?","Infancy (0–2), childhood (3–10), adolescence (11–18), early adulthood (19–45), middle adulthood (46–65), later adulthood (65+)."],
  ["Name four factors affecting health and wellbeing.","Diet, exercise, income, housing, relationships, education, access to services, substance use."],
  ["What is meant by holistic care?","Caring for the whole person — physical, intellectual, emotional and social needs together."],
  ["Name three life events that can affect development.","Starting school, moving house, bereavement, parental separation, serious illness, retirement."]]},
 {id:'values',n:'Care values & working practice',cards:[
  ["Name three care values.","Promoting rights, maintaining confidentiality, promoting equality and diversity (also dignity, choice, effective communication)."],
  ["Formal vs informal care?","Formal: paid professionals (nurses, care workers). Informal: unpaid family, friends or neighbours."],
  ["Why is confidentiality important, and when can it be broken?","It maintains trust and dignity; it may be broken if someone is at risk of serious harm."],
  ["Name four barriers to accessing services.","Physical, financial, geographical, language, cultural, and lack of awareness."],
  ["What is safeguarding?","Protecting vulnerable people from abuse, neglect and harm, including knowing how to report concerns."],
  ["Name three skills needed by a care worker.","Empathy, patience, communication, observation, teamwork, reliability."]]},
 {id:'promotion',n:'Health promotion',cards:[
  ["What is health promotion?","Activities that encourage people to improve their health, e.g. anti-smoking campaigns."],
  ["Name three methods of health promotion.","Mass media campaigns, school education, screening programmes, community workshops, legislation."],
  ["What makes a health campaign effective?","A clear targeted message, credible information, an achievable action and accessible support to change."],
  ["Give an example of primary, secondary and tertiary prevention.","Primary: vaccination. Secondary: screening for early detection. Tertiary: rehabilitation after illness."]]}]},

{id:'gov',n:'Government & Politics',c:'#1e3a8a',m:'GP',topics:[
 {id:'ni-institutions',n:'NI Assembly & Executive',cards:[
  ["How many MLAs sit in the NI Assembly?","90 — 5 for each of 18 constituencies."],
  ["Voting system for NI Assembly elections?","Single Transferable Vote (STV), a proportional system ranking candidates 1, 2, 3…"],
  ["What is the d'Hondt method used for in NI?","Allocating ministerial posts in the Executive in proportion to party strength."],
  ["What is a petition of concern?","A mechanism requiring cross-community support for a measure to pass, if signed by 30 MLAs."],
  ["What are the three strands of the Good Friday Agreement?","Strand 1: NI institutions. Strand 2: North–South bodies. Strand 3: British–Irish relations."],
  ["What are reserved, excepted and transferred matters?","Excepted stay with Westminster permanently (defence); reserved may transfer later (policing was); transferred are devolved (health, education)."]]},
 {id:'westminster',n:'Westminster & elections',cards:[
  ["How many MPs in the House of Commons?","650."],
  ["Voting system for Westminster elections?","First Past The Post — the candidate with the most votes in each constituency wins."],
  ["Give one advantage and one disadvantage of FPTP.","Advantage: simple and usually produces a strong single-party government. Disadvantage: disproportionate, with many wasted votes."],
  ["What are the main stages of a bill?","First reading, second reading, committee stage, report stage, third reading, the other House, then Royal Assent."],
  ["What is the role of the House of Lords?","To scrutinise and revise legislation and delay bills, but it cannot ultimately block money bills."],
  ["What is collective cabinet responsibility?","Ministers must publicly support government decisions or resign."]]},
 {id:'parties',n:'Parties, pressure groups & rights',cards:[
  ["Name the main parties in Northern Ireland.","DUP, Sinn Féin, Alliance, UUP, SDLP, plus smaller parties such as the TUV and Greens."],
  ["What is the difference between a political party and a pressure group?","Parties seek to form government; pressure groups seek to influence policy on specific issues."],
  ["What is the difference between insider and outsider pressure groups?","Insiders have access to decision makers and are consulted; outsiders use public campaigning to apply pressure."],
  ["What does the Human Rights Act 1998 do?","Incorporates the European Convention on Human Rights into UK law, allowing cases to be heard in UK courts."],
  ["What is the separation of powers?","Dividing power between legislature, executive and judiciary so each checks the others."]]}]}
];
const M=[
{n:'Practice testing (retrieval practice)',u:'High',why:'Pulling information out of memory strengthens it far more than putting it in again. The single best-supported technique.',how:['Flashcards: say the answer before you flip','Close the book and write everything you know','Do questions without notes, then check'],go:'cards'},
{n:'Spaced (distributed) practice',u:'High',why:'Reviewing over days and weeks beats one long cram. Forgetting a little between reviews makes the next recall stronger.',how:['Review new material after 1 day, then 3, 7, 14 days','Little and often: 30 minutes a day beats 4 hours on Sunday','Use the Leitner boxes here; they schedule it for you'],go:'mixed'},
{n:'Past papers & mark schemes',u:'High',why:'Practice testing in the exact format you\'ll be assessed. You learn command words, timing and what examiners reward.',how:['Download CCEA past papers and mark schemes from ccea.org.uk','Do them timed, then mark strictly with the mark scheme','Read Chief Examiner reports for common mistakes'],go:null},
{n:'Interleaving',u:'Moderate',why:'Mixing topics or problem types forces you to choose the right method, which is what exams make you do.',how:['Mix maths question types instead of 20 of the same','Swap subjects every block','Use Mixed review here'],go:'mixed'},
{n:'Elaborative interrogation',u:'Moderate',why:'Asking "why is this true?" links new facts to what you already know.',how:['For every fact ask why and how','Connect causes and consequences in history','Explain why a step in a method works'],go:null},
{n:'Self-explanation',u:'Moderate',why:'Explaining each step of a worked example to yourself exposes gaps in understanding.',how:['Talk through worked examples line by line','Say what each step does and why','Spot where you can\'t explain it, then revisit'],go:null},
{n:'Blurting',u:'Moderate',why:'A form of free recall: write everything you remember about a topic from memory, then check what you missed.',how:['Pick a topic, set 5–10 minutes','Write without notes','Check, and fill gaps in a different colour'],go:'blurt'},
{n:'Teach it (Feynman technique)',u:'Moderate',why:'Explaining in simple words to someone else (or a rubber duck) reveals what you don\'t really understand.',how:['Explain a topic as if to a 12-year-old','Where you get stuck, go back to the source','Simplify and use analogies'],go:null},
{n:'Dual coding',u:'Promising',why:'Combining words with visuals (diagrams, timelines, flowcharts) gives memory two routes to the same idea.',how:['Draw labelled diagrams from memory (cells, waterfalls)','Turn processes into flowcharts','Make timelines for history'],go:null},
{n:'Mind maps',u:'Moderate',why:'Useful for organising links between ideas, especially when drawn from memory rather than copied.',how:['Start from a blank page, not your notes','Add links between branches','Then check and add what you missed'],go:null},
{n:'Mnemonics',u:'Low',why:'Good for memorising lists and orders (DR & MRS VANDERTRAMP, SOH CAH TOA), weak for understanding.',how:['Use for fixed lists only','Pair with understanding','Make them silly to stick'],go:null},
{n:'Summarising',u:'Low',why:'Helps only if you\'re already good at it; often turns into copying.',how:['Condense notes from memory, not by copying','Limit yourself to one card per topic','Turn summaries into questions'],go:null},
{n:'Highlighting & underlining',u:'Low',why:'Feels productive but adds little. Can even make you focus on isolated facts.',how:['Highlight only once you\'ve read a whole section','Turn highlights into flashcard questions'],go:null},
{n:'Re-reading',u:'Low',why:'Creates a feeling of familiarity, not memory. The most common and among the least effective methods.',how:['Read once, then close it and test yourself','Swap re-reading for blurting'],go:null}
];

